package marketdata

import (
	"context"
	"errors"
	"fmt"

	"github.com/devshoe/gokiteconnect/models"
)

// DefaultSyncListName names the list of instruments kept in the candles
// database by default. It is saved as an auto-generated list owned by
// models.AdminUser.
const DefaultSyncListName = "DEFAULT SYNC"

// DefaultSyncIndices are the indices the default sync list starts with:
// the NSE indices tradebot's DEFAULT collection keeps, and the BSE indices
// with derivatives.
var DefaultSyncIndices = []models.InstrumentID{
	"NSE:NIFTY 50",
	"NSE:NIFTY BANK",
	"NSE:NIFTY FIN SERVICE",
	"NSE:NIFTY MID SELECT",
	"NSE:NIFTY NEXT 50",
	"NSE:INDIA VIX",
	"BSE:SENSEX",
	"BSE:BANKEX",
	"NSE:NIFTY 100",
	"NSE:NIFTY 200",
	"NSE:NIFTY 500",
	"NSE:NIFTY100 EQL WGT",
	"NSE:NIFTY AUTO",
	"NSE:NIFTY COMMODITIES",
	"NSE:NIFTY CONSR DURBL",
	"NSE:NIFTY FINSRV25 50",
	"NSE:NIFTY FMCG",
	"NSE:NIFTY HEALTHCARE",
	"NSE:NIFTY IT",
	"NSE:NIFTY LARGEMID250",
	"NSE:NIFTY MEDIA",
	"NSE:NIFTY METAL",
	"NSE:NIFTY MICROCAP250",
	"NSE:NIFTY MIDCAP 100",
	"NSE:NIFTY MIDCAP 150",
	"NSE:NIFTY MIDCAP 50",
	"NSE:NIFTY MIDSML 400",
	"NSE:NIFTY MIDSML HLTH",
	"NSE:NIFTY OIL AND GAS",
	"NSE:NIFTY PHARMA",
	"NSE:NIFTY PSU BANK",
	"NSE:NIFTY PVT BANK",
	"NSE:NIFTY REALTY",
	"NSE:NIFTY SMLCAP 250",
	"NSE:NIFTY SMLCAP 50",
	"NSE:NIFTY TOTAL MKT",
	"NSE:NIFTY500 MULTICAP",
}

// Catalog finds the default sync list's instruments.
// *kite.InstrumentCatalog implements it.
type Catalog interface {
	Get(ctx context.Context, id models.InstrumentID) (models.Instrument, error)
	ListFO(ctx context.Context, exchanges ...string) ([]models.Instrument, error)
}

// ListSaver saves an auto-generated list, replacing its items.
// *repository.ListsSQLiteRepository implements it.
type ListSaver interface {
	ReplaceAutoGeneratedList(ctx context.Context, list models.List) (models.List, error)
}

// DefaultSyncList is the list of instruments synced by default: the
// DefaultSyncIndices the catalog has, then every NSE stock and index with
// futures or options. Indices missing from the catalog are skipped.
func DefaultSyncList(ctx context.Context, catalog Catalog) (models.List, error) {
	list := models.List{CreatedBy: models.AdminUser, Name: DefaultSyncListName, AutoGenerated: true}
	seen := make(map[models.InstrumentID]bool)
	add := func(id models.InstrumentID) {
		if !seen[id] {
			seen[id] = true
			list.Items = append(list.Items, models.ListItem{InstrumentID: id})
		}
	}
	for _, id := range DefaultSyncIndices {
		instrument, err := catalog.Get(ctx, id)
		if errors.Is(err, models.ErrNotFound) {
			continue
		}
		if err != nil {
			return models.List{}, fmt.Errorf("default sync list: %w", err)
		}
		add(instrument.ID)
	}
	underlyings, err := catalog.ListFO(ctx, "NSE")
	if err != nil {
		return models.List{}, fmt.Errorf("default sync list: %w", err)
	}
	for _, instrument := range underlyings {
		add(instrument.ID)
	}
	if len(list.Items) == 0 {
		return models.List{}, errors.New("default sync list: the catalog has none of its instruments")
	}
	return list, nil
}

// RebuildDefaultSyncList builds the default sync list from the catalog and
// saves it, replacing the stored one.
func RebuildDefaultSyncList(ctx context.Context, catalog Catalog, lists ListSaver) (models.List, error) {
	list, err := DefaultSyncList(ctx, catalog)
	if err != nil {
		return models.List{}, err
	}
	return lists.ReplaceAutoGeneratedList(ctx, list)
}
